import { CallToAction } from './call-to-action';
import { Features } from './features';
import { Hero } from './hero';
import { LogoCloud } from './logo-cloud';
import { SiteFooter } from './site-footer';
import { SiteHeader } from './site-header';

export default function Marketing01() {
  return (
    <div className='flex min-h-screen flex-col'>
      <SiteHeader />
      <main className='flex-1'>
        <Hero />
        <LogoCloud />
        <Features />
        <CallToAction />
      </main>
      <SiteFooter />
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';

import { Button } from '@/registry/ndeko/ui/button';
import { Collapsible } from '@/registry/ndeko/ui/collapsible';

import { LoomboardMark } from './brand-mark';
import { DesktopNav } from './desktop-nav';
import { MobileMenuPanel, MobileMenuTrigger } from './mobile-menu';
import { scrollToSection, sectionHashOf } from './section-link';

const MENU_COLLAPSE_MS = 200;

export function SiteHeader() {
  const [isOpen, setIsOpen] = useState(false);
  const [pendingHash, setPendingHash] = useState<string | null>(null);

  useEffect(() => {
    if (pendingHash === null) {
      return;
    }
    const timeout = window.setTimeout(() => {
      scrollToSection(pendingHash);
      setPendingHash(null);
    }, MENU_COLLAPSE_MS);
    return () => window.clearTimeout(timeout);
  }, [pendingHash]);

  function navigateFromMenu(event: React.MouseEvent<HTMLAnchorElement>) {
    const href = event.currentTarget.getAttribute('href');
    const sectionHash = sectionHashOf(href);
    setIsOpen(false);
    if (sectionHash === null) {
      return;
    }
    event.preventDefault();
    setPendingHash(sectionHash);
  }

  return (
    <header className='px-4 sm:px-6 lg:px-8'>
      <Collapsible
        open={isOpen}
        onOpenChange={setIsOpen}
        className='mx-auto max-w-6xl'
      >
        <div className='flex h-16 items-center gap-6'>
          <a
            href='#'
            aria-current='page'
            className='focus-visible:ring-ring/25 flex items-center gap-2 rounded-md text-sm font-semibold outline-none focus-visible:ring-[3px]'
          >
            <LoomboardMark />
            Loomboard
          </a>
          <DesktopNav />
          <div className='ms-auto hidden items-center gap-1 md:flex'>
            <Button
              variant='ghost'
              nativeButton={false}
              render={<a href='#' />}
            >
              Sign in
            </Button>
            <Button
              variant='outline'
              nativeButton={false}
              render={<a href='#' />}
            >
              Start free
            </Button>
          </div>
          <div className='ms-auto md:hidden'>
            <MobileMenuTrigger isOpen={isOpen} />
          </div>
        </div>
        <MobileMenuPanel onNavigate={navigateFromMenu} />
      </Collapsible>
    </header>
  );
}

import { ArrowRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  NavigationMenu,
  NavigationMenuContent,
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuList,
  NavigationMenuTrigger,
  navigationMenuTriggerStyle,
} from '@/registry/ndeko/ui/navigation-menu';

import {
  FEATURED_GUIDE,
  type MenuLink,
  PRODUCT_LINKS,
  RESOURCE_LINKS,
  SOLUTION_GROUPS,
} from './data';

function IconLink({ link }: { link: MenuLink }) {
  return (
    <NavigationMenuLink
      href={link.href}
      closeOnClick
      className='flex-row items-start gap-3'
    >
      <span className='keycap-3d text-muted-foreground flex size-8 shrink-0 items-center justify-center rounded-lg'>
        <link.icon />
      </span>
      <span className='flex flex-col gap-0.5'>
        <span className='text-foreground font-medium'>{link.title}</span>
        <span className='text-muted-foreground text-xs'>
          {link.description}
        </span>
      </span>
    </NavigationMenuLink>
  );
}

function ProductPanel() {
  return (
    <ul className='grid gap-1 sm:w-[34rem] sm:grid-cols-2'>
      {PRODUCT_LINKS.map((link) => (
        <li key={link.title}>
          <IconLink link={link} />
        </li>
      ))}
    </ul>
  );
}

function SolutionsPanel() {
  return (
    <div className='grid gap-4 p-1 sm:w-[24rem] sm:grid-cols-2'>
      {SOLUTION_GROUPS.map((group) => (
        <div key={group.label} className='flex flex-col gap-1'>
          <p className='text-muted-foreground px-2.5 pt-1.5 text-xs font-medium'>
            {group.label}
          </p>
          <ul className='flex flex-col'>
            {group.links.map((link) => (
              <li key={link.title}>
                <NavigationMenuLink
                  href={link.href}
                  className='text-foreground py-2'
                >
                  {link.title}
                </NavigationMenuLink>
              </li>
            ))}
          </ul>
        </div>
      ))}
    </div>
  );
}

function ResourcesPanel() {
  return (
    <div className='grid gap-2 sm:w-[38rem] sm:grid-cols-[minmax(0,1fr)_15rem]'>
      <ul className='flex flex-col gap-1'>
        {RESOURCE_LINKS.map((link) => (
          <li key={link.title}>
            <IconLink link={link} />
          </li>
        ))}
      </ul>
      <NavigationMenuLink
        href={FEATURED_GUIDE.href}
        className='group/guide p-0 transition-[scale] duration-150 ease-(--ease-out-strong) hover:bg-transparent active:scale-[0.97]'
      >
        <span className='bg-foreground/[0.03] group-hover/guide:bg-foreground/[0.05] flex h-full flex-col justify-between gap-6 rounded-lg p-4 transition-colors'>
          <span className='flex flex-col gap-1.5'>
            <span className='text-primary-ink text-xs font-medium'>
              {FEATURED_GUIDE.label}
            </span>
            <span className='text-foreground text-sm font-medium text-balance'>
              {FEATURED_GUIDE.title}
            </span>
            <span className='text-muted-foreground text-xs'>
              {FEATURED_GUIDE.description}
            </span>
          </span>
          <span className='text-primary-ink inline-flex items-center gap-1 text-xs font-medium'>
            Read the guide
            <ArrowRightIcon className='size-3.5' />
          </span>
        </span>
      </NavigationMenuLink>
    </div>
  );
}

export function DesktopNav() {
  return (
    <NavigationMenu className='hidden md:block'>
      <NavigationMenuList>
        <NavigationMenuItem value='product'>
          <NavigationMenuTrigger>Product</NavigationMenuTrigger>
          <NavigationMenuContent>
            <ProductPanel />
          </NavigationMenuContent>
        </NavigationMenuItem>
        <NavigationMenuItem value='solutions'>
          <NavigationMenuTrigger>Solutions</NavigationMenuTrigger>
          <NavigationMenuContent>
            <SolutionsPanel />
          </NavigationMenuContent>
        </NavigationMenuItem>
        <NavigationMenuItem value='resources'>
          <NavigationMenuTrigger>Resources</NavigationMenuTrigger>
          <NavigationMenuContent>
            <ResourcesPanel />
          </NavigationMenuContent>
        </NavigationMenuItem>
        <NavigationMenuItem>
          <NavigationMenuLink
            href='#'
            className={cn(navigationMenuTriggerStyle, 'flex-row py-0')}
          >
            Pricing
          </NavigationMenuLink>
        </NavigationMenuItem>
      </NavigationMenuList>
    </NavigationMenu>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';

import { MenuIcon, XIcon } from '@/registry/ndeko/lib/icons';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/registry/ndeko/ui/accordion';
import { Button } from '@/registry/ndeko/ui/button';
import {
  CollapsibleContent,
  CollapsibleTrigger,
} from '@/registry/ndeko/ui/collapsible';

import {
  type MenuLink,
  PRODUCT_LINKS,
  RESOURCE_LINKS,
  SOLUTION_GROUPS,
} from './data';

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const ICON_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const ROW =
  'flex h-10 items-center gap-3 rounded-md px-2 text-sm text-foreground outline-none transition-colors hover:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25';

function iconVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return ICON_VARIANTS;
}

function toggleGlyphOf(isOpen: boolean) {
  if (isOpen) {
    return { key: 'close', icon: <XIcon /> };
  }
  return { key: 'open', icon: <MenuIcon /> };
}

function toggleLabelOf(isOpen: boolean) {
  if (isOpen) {
    return 'Close menu';
  }
  return 'Open menu';
}

export function MobileMenuTrigger({ isOpen }: { isOpen: boolean }) {
  const shouldReduceMotion = useReducedMotion();
  const iconVariants = iconVariantsOf(shouldReduceMotion);
  const glyph = toggleGlyphOf(isOpen);

  return (
    <CollapsibleTrigger
      render={
        <Button
          variant='ghost'
          size='icon'
          className='md:hidden'
          aria-label={toggleLabelOf(isOpen)}
        />
      }
    >
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={glyph.key}
          className='flex'
          variants={iconVariants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
        >
          {glyph.icon}
        </motion.span>
      </AnimatePresence>
    </CollapsibleTrigger>
  );
}

type NavigateHandler = (event: React.MouseEvent<HTMLAnchorElement>) => void;

type MobileLinksProps = {
  links: MenuLink[];
  onNavigate: NavigateHandler;
};

function MobileIconLinks({ links, onNavigate }: MobileLinksProps) {
  return (
    <ul className='flex flex-col'>
      {links.map((link) => (
        <li key={link.title}>
          <a href={link.href} className={ROW} onClick={onNavigate}>
            <span className='keycap-3d text-muted-foreground flex size-7 shrink-0 items-center justify-center rounded-lg'>
              <link.icon className='size-3.5' />
            </span>
            {link.title}
          </a>
        </li>
      ))}
    </ul>
  );
}

export function MobileMenuPanel({
  onNavigate,
}: {
  onNavigate: NavigateHandler;
}) {
  return (
    <CollapsibleContent className='md:hidden'>
      <nav aria-label='Main' className='flex flex-col gap-4 pt-2 pb-5'>
        <Accordion defaultValue={['product']}>
          <AccordionItem value='product' className='border-b-0'>
            <AccordionTrigger className='px-2 text-sm'>
              Product
            </AccordionTrigger>
            <AccordionContent>
              <MobileIconLinks links={PRODUCT_LINKS} onNavigate={onNavigate} />
            </AccordionContent>
          </AccordionItem>
          <AccordionItem value='solutions' className='border-b-0'>
            <AccordionTrigger className='px-2 text-sm'>
              Solutions
            </AccordionTrigger>
            <AccordionContent className='flex flex-col gap-3'>
              {SOLUTION_GROUPS.map((group) => (
                <div key={group.label} className='flex flex-col gap-0.5'>
                  <p className='text-muted-foreground px-2 py-1 text-xs font-medium'>
                    {group.label}
                  </p>
                  <ul className='flex flex-col'>
                    {group.links.map((link) => (
                      <li key={link.title}>
                        <a
                          href={link.href}
                          className={ROW}
                          onClick={onNavigate}
                        >
                          {link.title}
                        </a>
                      </li>
                    ))}
                  </ul>
                </div>
              ))}
            </AccordionContent>
          </AccordionItem>
          <AccordionItem value='resources' className='border-b-0'>
            <AccordionTrigger className='px-2 text-sm'>
              Resources
            </AccordionTrigger>
            <AccordionContent>
              <MobileIconLinks links={RESOURCE_LINKS} onNavigate={onNavigate} />
            </AccordionContent>
          </AccordionItem>
        </Accordion>
        <a href='#' className={ROW} onClick={onNavigate}>
          Pricing
        </a>
        <div className='flex flex-col gap-2 px-2'>
          <Button
            variant='outline'
            size='lg'
            nativeButton={false}
            render={<a href='#' />}
          >
            Sign in
          </Button>
          <Button size='lg' nativeButton={false} render={<a href='#' />}>
            Start free
          </Button>
        </div>
      </nav>
    </CollapsibleContent>
  );
}

const SECTION_HASH_PATTERN = /^#.+/;

export function sectionHashOf(href: string | null) {
  if (href === null) {
    return null;
  }
  const isSectionHash = SECTION_HASH_PATTERN.test(href);
  if (!isSectionHash) {
    return null;
  }
  return href;
}

export function scrollToSection(hash: string) {
  const id = hash.slice(1);
  const target = document.getElementById(id);
  target?.scrollIntoView();
}

import { ArrowRightIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

import { BoardStage } from './board-stage';
import { HERO } from './data';

export function Hero() {
  return (
    <section className='px-4 pt-16 pb-4 sm:px-6 sm:pt-24 sm:pb-6 lg:px-8'>
      <div className='mx-auto flex max-w-3xl flex-col items-center gap-5 text-center'>
        <p className='text-primary-ink text-xs font-medium'>{HERO.eyebrow}</p>
        <h1 className='text-4xl font-semibold text-balance sm:text-5xl'>
          {HERO.title}
        </h1>
        <p className='text-muted-foreground max-w-xl text-base text-pretty'>
          {HERO.description}
        </p>
        <div className='flex flex-wrap justify-center gap-2 pt-1'>
          <Button size='lg' nativeButton={false} render={<a href='#' />}>
            {HERO.primaryAction}
            <ArrowRightIcon />
          </Button>
          <Button
            size='lg'
            variant='outline'
            nativeButton={false}
            render={<a href='#' />}
          >
            {HERO.secondaryAction}
          </Button>
        </div>
      </div>
      <div className='relative mx-auto mt-12 max-w-6xl [mask-image:linear-gradient(to_bottom,black_58%,transparent_96%)] px-2 pt-2 sm:mt-16'>
        <BoardStage />
        <div
          aria-hidden='true'
          className='pointer-events-none absolute inset-x-0 bottom-0 h-56 [mask-image:linear-gradient(to_bottom,transparent,black_75%)] backdrop-blur-[3px]'
        />
      </div>
    </section>
  );
}

'use client';

import {
  DndContext,
  DragOverlay,
  KeyboardSensor,
  MeasuringStrategy,
  MouseSensor,
  TouchSensor,
  defaultDropAnimationSideEffects,
  useSensor,
  useSensors,
  type Announcements,
  type CollisionDetection,
  type DragEndEvent,
  type DragMoveEvent,
  type DragOverEvent,
  type DragStartEvent,
  type DropAnimation,
  type UniqueIdentifier,
} from '@dnd-kit/core';
import { sortableKeyboardCoordinates } from '@dnd-kit/sortable';
import { useMotionValue, useReducedMotion } from 'motion/react';
import { useCallback, useEffect, useId, useRef, useState } from 'react';

import { LayoutGridIcon } from '@/registry/ndeko/lib/icons';
import { Badge } from '@/registry/ndeko/ui/badge';

import { DragOverlayCard, PersonAvatar } from './board-card';
import { BoardLane } from './board-lane';
import {
  detectBoardCollision,
  laneOf,
  moveAcrossLanes,
  reorderInLane,
  targetLaneOf,
} from './board-moves';
import {
  BOARD,
  type BoardCard,
  CARDS,
  COLUMNS,
  type Columns,
  LANES,
  type LaneId,
  PEOPLE,
} from './data';

const MEASURING = { droppable: { strategy: MeasuringStrategy.Always } };

const DROP_ANIMATION: DropAnimation = {
  duration: 220,
  easing: 'cubic-bezier(0.23, 1, 0.32, 1)',
  sideEffects: defaultDropAnimationSideEffects({
    styles: { active: { opacity: '0.4' } },
  }),
};

const SCREEN_READER_INSTRUCTIONS = {
  draggable:
    'To pick up a card, press Space or Enter. Use the arrow keys to move it between lanes and cards, Space or Enter to drop it, Escape to cancel.',
};

const BOARD_LABEL = `${BOARD.title}, ${BOARD.week}`;

function dropAnimationOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return null;
  }
  return DROP_ANIMATION;
}

function laneTitleOf(laneId: LaneId | null) {
  const lane = LANES.find((candidate) => candidate.id === laneId);
  if (lane) {
    return lane.title;
  }
  return 'the board';
}

function cardTitleOf(cardId: UniqueIdentifier) {
  const card = CARDS[String(cardId)];
  return card.title;
}

function BoardHeader() {
  return (
    <div className='flex items-center gap-2.5 px-5 pt-4 pb-2'>
      <span className='gem-plate flex size-6 shrink-0 items-center justify-center rounded-md [--gem:var(--primary)]'>
        <LayoutGridIcon className='size-3.5' />
      </span>
      <p className='truncate text-sm font-medium'>{BOARD.title}</p>
      <Badge
        variant='secondary'
        className='text-muted-foreground hidden sm:inline-flex'
      >
        {BOARD.week}
      </Badge>
      <div className='ms-auto flex shrink-0 -space-x-1.5'>
        {PEOPLE.map((person) => (
          <PersonAvatar
            key={person.name}
            person={person}
            className='ring-card size-6 text-[10px] ring-2'
          />
        ))}
      </div>
    </div>
  );
}

export function BoardStage() {
  const [columns, setColumns] = useState<Columns>(COLUMNS);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [targetLaneId, setTargetLaneId] = useState<LaneId | null>(null);
  const columnsRef = useRef(columns);
  const snapshotRef = useRef<Columns | null>(null);
  const lastOverIdRef = useRef<UniqueIdentifier | null>(null);
  const movedLaneRef = useRef(false);
  const dragX = useMotionValue(0);
  const shouldReduceMotion = useReducedMotion();
  const dndContextId = useId();
  const sensors = useSensors(
    useSensor(MouseSensor, { activationConstraint: { distance: 4 } }),
    useSensor(TouchSensor, {
      activationConstraint: { delay: 180, tolerance: 6 },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  let activeCard: BoardCard | null = null;
  if (activeId) {
    activeCard = CARDS[activeId];
  }

  useEffect(() => {
    columnsRef.current = columns;
    const frame = requestAnimationFrame(() => {
      movedLaneRef.current = false;
    });
    return () => cancelAnimationFrame(frame);
  }, [columns]);

  const collisionDetection = useCallback<CollisionDetection>((args) => {
    const hits = detectBoardCollision(args, columnsRef.current);
    if (hits.length > 0) {
      lastOverIdRef.current = hits[0].id;
      return hits;
    }
    if (movedLaneRef.current) {
      lastOverIdRef.current = args.active.id;
    }
    const lastOverId = lastOverIdRef.current;
    if (lastOverId) {
      return [{ id: lastOverId }];
    }
    return [];
  }, []);

  const announcements: Announcements = {
    onDragStart({ active }) {
      const lane = laneOf(columnsRef.current, String(active.id));
      return `Picked up ${cardTitleOf(active.id)} in ${laneTitleOf(lane)}`;
    },
    onDragOver({ active, over }) {
      if (!over) {
        return `${cardTitleOf(active.id)} is no longer over a lane`;
      }
      const lane = targetLaneOf(columnsRef.current, String(over.id));
      return `${cardTitleOf(active.id)} is over ${laneTitleOf(lane)}`;
    },
    onDragEnd({ active }) {
      const lane = laneOf(columnsRef.current, String(active.id));
      return `${cardTitleOf(active.id)} dropped in ${laneTitleOf(lane)}`;
    },
    onDragCancel({ active }) {
      return `Moving ${cardTitleOf(active.id)} was cancelled`;
    },
  };

  function handleDragStart({ active }: DragStartEvent) {
    const cardId = String(active.id);
    snapshotRef.current = columns;
    dragX.set(0);
    setActiveId(cardId);
    setTargetLaneId(laneOf(columns, cardId));
  }

  function handleDragMove({ delta }: DragMoveEvent) {
    dragX.set(delta.x);
  }

  function handleDragOver({ active, over }: DragOverEvent) {
    if (!over) {
      return;
    }
    const overLane = targetLaneOf(columnsRef.current, String(over.id));
    setTargetLaneId(overLane);
    const fromLane = laneOf(columnsRef.current, String(active.id));
    const isOtherLane = fromLane !== overLane;
    if (!isOtherLane) {
      return;
    }
    movedLaneRef.current = true;
    setColumns((previous) => moveAcrossLanes(previous, active, over));
  }

  function handleDragEnd({ active, over }: DragEndEvent) {
    setActiveId(null);
    setTargetLaneId(null);
    snapshotRef.current = null;
    if (!over) {
      return;
    }
    const activeCardId = String(active.id);
    const overId = String(over.id);
    setColumns((previous) => reorderInLane(previous, activeCardId, overId));
  }

  function handleDragCancel() {
    const snapshot = snapshotRef.current;
    if (snapshot) {
      setColumns(snapshot);
    }
    snapshotRef.current = null;
    setActiveId(null);
    setTargetLaneId(null);
  }

  return (
    <section
      aria-label={BOARD_LABEL}
      className='bg-card hairline-ring ring-border overflow-hidden rounded-2xl shadow-[0_1px_2px_rgb(0_0_0/0.04),0_12px_32px_-16px_rgb(0_0_0/0.12)]'
    >
      <BoardHeader />
      <DndContext
        id={dndContextId}
        sensors={sensors}
        collisionDetection={collisionDetection}
        measuring={MEASURING}
        accessibility={{
          announcements,
          screenReaderInstructions: SCREEN_READER_INSTRUCTIONS,
        }}
        onDragStart={handleDragStart}
        onDragMove={handleDragMove}
        onDragOver={handleDragOver}
        onDragEnd={handleDragEnd}
        onDragCancel={handleDragCancel}
      >
        <div className='relative overflow-x-auto overscroll-x-contain max-md:snap-x max-md:snap-proximity max-md:scroll-px-2'>
          <div className='grid h-[34rem] min-w-[42rem] grid-cols-3 grid-rows-[minmax(0,1fr)] gap-2 p-2 sm:h-[38rem]'>
            {LANES.map((lane) => (
              <BoardLane
                key={lane.id}
                lane={lane}
                cardIds={columns[lane.id]}
                isTarget={targetLaneId === lane.id}
              />
            ))}
          </div>
        </div>
        <DragOverlay dropAnimation={dropAnimationOf(shouldReduceMotion)}>
          {activeCard && <DragOverlayCard card={activeCard} dragX={dragX} />}
        </DragOverlay>
      </DndContext>
    </section>
  );
}

'use client';

import { useDroppable } from '@dnd-kit/core';
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { useReducedMotion } from 'motion/react';
import { memo } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { cn } from '@/registry/ndeko/lib/utils';

import { BoardCardBody, CARD_SURFACE, cardLabelOf } from './board-card';
import { CARDS, type Lane } from './data';

const SORT_TRANSITION = {
  duration: 220,
  easing: 'cubic-bezier(0.23, 1, 0.32, 1)',
};

function sortTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return null;
  }
  return SORT_TRANSITION;
}

function cardCountLabel(count: number) {
  if (count === 1) {
    return '1 card';
  }
